    function selectEventCategory(category){clearRoundRetry();stopQuoteFeed();stopFeed();stopClock();roundSyncPending=false;roundSyncAwaitingFeed=false;market=category;eventMode=true;currentEvent=null;eventDeadline=0;currentRound=null;clearBetSide();roundLockDeadline=0;roundSyncedAt=0;readyPrice=false;historyHydrated=false;clearRoundMeta();if(cardTop)cardTop.style.display='';updateMenu();setChoiceLabels(true);if(card)card.classList.remove('trend-up','trend-down','trend-flat');if(card)card.classList.add('event-mode');if(questionImage){questionImage.style.backgroundImage='';questionImage.classList.remove('has-image')}if(chart)chart.classList.add('event-mode');if(question)question.textContent='Loading '+category+' prediction...';if(symbolFallback)symbolFallback.textContent=category==='tech'?'✦':category==='culture'?'★':'◉';if(startLabel)startLabel.textContent='Yes pool';if(liveLabel)liveLabel.textContent='No pool';resetMarketPrice(start,'Loading');resetMarketPrice(live,'Loading');if(trendLabel)trendLabel.textContent='Choose Yes or No';resetCountdownText('--:--');syncBetAvailability();var id=uid(),headers={},my=seq;if(id&&telegramInitData())headers['x-telegram-init-data']=telegramInitData();fetch('/app/api/prediction-events?userId='+encodeURIComponent(id),{cache:'no-store',headers:headers}).then(function(r){return r.json()}).then(function(d){if(my!==seq||market!==category||!eventMode)return;var events=(d&&d.events||[]).filter(function(e){return e&&e.category===category&&(e.status==='open'||e.status==='locked')});if(!events.length)throw new Error('No live prediction');renderEvent(events[0]);updateBalance(d)}).catch(function(){if(my!==seq||market!==category||!eventMode)return;if(question)question.textContent='No live '+category+' prediction yet';if(trendLabel)trendLabel.textContent='Check back after an admin publishes one';if(eventSummary)eventSummary.style.display='none';if(category==='world')selectMarket('bitcoin')})}
