    function selectMarket(id){if(marketUnavailable(id))return;if(EVENT_CATEGORIES[id]){selectEventCategory(id);return}if(!MARKETS[id])return;clearRoundRetry();stopQuoteFeed();stopFeed();stopClock();roundSyncPending=false;roundSyncAwaitingFeed=false;market=id;priceProvider=id==='bitcoin'?'':'vexa';if(id==='bitcoin')priceRtdsTopic=bitcoinTimeframe==='1h'?'crypto_prices':'crypto_prices_twap_sixty';eventMode=false;currentEvent=null;eventDeadline=0;clearBetSide();clearRoundMeta();if(cardTop)cardTop.style.display=id==='bitcoin'?'':'none';if(card)card.classList.remove('event-mode');if(chart)chart.classList.remove('event-mode');if(eventSummary)eventSummary.style.display='none';setChoiceLabels(false);if(startLabel)startLabel.textContent=id==='bitcoin'?'Start':'Month start';if(liveLabel)liveLabel.textContent='Live';values=[];sampleTimes=[];historyValues=[];historyHydrated=false;current=0;last=0;raw=0;priceTarget=0;scaleMin=0;scaleMax=0;scaleFrameAt=0;entry=0;readyPrice=false;currentRound=null;roundLockDeadline=0;roundSyncedAt=0;lastPointAt=0;lastFeedTimestamp=0;chartSuspendedAt=0;chartResumeEaseUntil=0;reconnectDelay=6000;showLoading();updateMenu();if(question)question.textContent=id==='bitcoin'?'Bitcoin up or down? · '+bitcoinTimeframe.toUpperCase():cfg().question;renderImage();if(result){result.className='predict-zone-result-strip';result.innerHTML=''}var my=seq,selectedMarket=market;syncRound(my,selectedMarket).then(function(ok){if(my!==seq||selectedMarket!==market||eventMode)return;if(!ws&&!reconnectTimer)connectFeed(my,selectedMarket);if(ok)startClock()})}
    function applyMarketAccess(){if(!isActive()){if(predictPreparing&&marketUnavailable(market))finishPredictPreparation();preparePredictFromHome();return}var first=null;['bitcoin','oil','gold'].some(function(id){if(!marketUnavailable(id)){first=id;return true}return false});if(marketUnavailable(market)){clearRoundRetry();stopQuoteFeed();stopFeed();stopClock();clearBetSide();currentRound=null;roundSyncedAt=0;readyPrice=false;if(first)selectMarket(first);else{if(question)question.textContent='Predictions are temporarily unavailable';if(trendLabel)trendLabel.textContent='Markets locked'}}else if(!currentRound&&!ws&&!roundSyncPending)selectMarket(market)}
    function hasReusableRound(){if(eventMode||!currentRound||!readyPrice||String(currentRound.status||'')==='starting')return false;var ends=Date.parse(currentRound.endsAt||'');return isFinite(ends)&&ends>roundNow()}
    function refreshRoundIfNeeded(my,id){if(!currentRound||String(currentRound.status||'')==='starting'||!roundSyncedAt||Date.now()-roundSyncedAt>=5000)return syncRound(my,id).then(function(ok){if(ok&&my===seq&&id===market&&!eventMode)startClock();return ok});requestRoundRealtime(currentRound.id,id);return Promise.resolve(true)}
    function suspend(){if(runtimeSuspended)return;runtimeSuspended=true;setHistoryDrawer(false);if(regionPanel&&regionPanel.classList.contains('is-open'))setRegionSheet(false);clearRoundRetry();roundSyncPending=false;roundSyncAwaitingFeed=false;freezeChartTimeline();stopClock();pauseQuoteFeed();stopFeed();if(presetEditing)setPresetEditing(false)}
    function resume(){if(!isActive())return;var wasSuspended=runtimeSuspended;if(predictPreparing){predictPreparing=false;if(predictPrepareTimer){clearTimeout(predictPrepareTimer);predictPrepareTimer=0}}runtimeSuspended=false;if(!runtimeStarted){runtimeStarted=true;loadImages();loadGramUsd();if((!predictPrepareUser||predictPrepareUser===uid())&&(hasReusableRound()||(predictPrepareUser&&(roundRequest||(currentRound&&String(currentRound.status||'')!=='starting'&&Date.parse(currentRound.endsAt||'')>roundNow()))))){resumeChartTimeline();var firstMy=seq,firstId=market;if(!ws&&!reconnectTimer)connectFeed(firstMy,firstId);if(currentRound)syncQuoteFeed(currentRound);if(readyPrice)draw();startChartMotion();startClock();if(roundRequest)roundRequest.promise.then(function(ok){if(ok&&firstMy===seq&&firstId===market&&isActive())startClock()});else refreshRoundIfNeeded(firstMy,firstId);return}selectMarket('bitcoin');return}if(eventMode){if(wasSuspended&&(!currentEvent||eventDeadline<=Date.now())){selectEventCategory(market);return}if(currentEvent&&!clockTimer)startClock();return}if(wasSuspended){resumeChartTimeline();var my=seq,id=market;if(!ws&&!reconnectTimer)connectFeed(my,id);if(currentRound)syncQuoteFeed(currentRound);if(readyPrice&&hasReusableRound())startChartMotion();if(currentRound)startClock();refreshRoundIfNeeded(my,id)}else{if(readyPrice)startChartMotion();if(!clockTimer&&currentRound)startClock();if(!ws&&!reconnectTimer)connectFeed(seq,market);if(currentRound)syncQuoteFeed(currentRound);resumeRoundSync(seq,market)}}
