    setupHistoryDrawer();
    if(timeframeSelect)timeframeSelect.addEventListener('change',function(){var next=String(timeframeSelect.value||'');if(busy||eventMode||market!=='bitcoin'||marketUnavailable('bitcoin')||['5m','15m'].indexOf(next)<0){timeframeSelect.value=bitcoinTimeframe;return}if(next===bitcoinTimeframe)return;rememberSettlementWatch(currentRound);bitcoinTimeframe=next;selectMarket('bitcoin')});
