    root.addEventListener('click',function(e){var target=e.target;if(!target)return;var mode=target.closest&&target.closest('[data-predict-chart-mode]');if(mode){e.preventDefault();setChartMode(mode.getAttribute('data-predict-chart-mode'));return}var edit=target.closest&&target.closest('[data-predict-preset-edit]');if(edit){e.preventDefault();setPresetEditing(!presetEditing);return}var preset=target.closest&&target.closest('[data-predict-bet-preset]');if(preset){e.preventDefault();if(presetEditing){editPresetWithNativePrompt(preset);return}submitBet(preset.getAttribute('data-predict-bet-preset'));return}var choice=target.closest&&target.closest('[data-predict-choice]');if(choice){e.preventDefault();selectBetSide(choice.getAttribute('data-predict-choice'));return}},true);
